function renderQuiz(questions) {
  document.getElementById('quizBody').innerHTML = questions.map((item, qi) => `
    <div class="quiz-item" data-q="${qi}">
      <div class="quiz-q">${qi + 1}. ${item.q}</div>
      ${item.options.map((opt, oi) => `
        <label class="quiz-opt" data-oi="${oi}">
          <input type="radio" name="q${qi}" value="${oi}" />
          <span>${opt}</span>
        </label>
      `).join('')}
    </div>
  `).join('');
  document.getElementById('quizActions').style.display = 'flex';
  document.getElementById('btnCheck').style.display = '';
  document.getElementById('btnRetry').style.display = 'none';
  document.getElementById('quizFeedback').className = 'quiz-feedback';
}

function checkAnswers() {
  const quiz = listeningState.quiz?.questions || [];
  const ans  = quiz.map((_, qi) => {
    const sel = document.querySelector(`input[name="q${qi}"]:checked`);
    return sel ? Number(sel.value) : null;
  });
  if (ans.some(a => a === null)) { lsShowToast('Responde todas las preguntas antes de comprobar'); return; }

  let correct = 0;
  quiz.forEach((item, qi) => {
    const block   = document.querySelector(`.quiz-item[data-q="${qi}"]`);
    const isRight = ans[qi] === item.answer;
    if (isRight) correct++;
    block.querySelectorAll('.quiz-opt').forEach(opt => {
      opt.classList.add('disabled');
      const oi  = Number(opt.dataset.oi);
      const inp = opt.querySelector('input');
      if (oi === item.answer) opt.classList.add('correct-ans');
      else if (inp?.checked) opt.classList.add('selected-wrong');
      if (inp) inp.disabled = true;
    });
  });

  const fb    = document.getElementById('quizFeedback');
  const allOk = correct === quiz.length;
  if (allOk) {
    fb.className   = 'quiz-feedback pass';
    fb.textContent = `🎉 ¡Perfecto! Acertaste las ${quiz.length} preguntas. ¡Lección completada!`;
    document.getElementById('btnCheck').style.display = 'none';
    setTimeout(() => completeLesson(listeningState.idx), 900);
  } else {
    fb.className   = 'quiz-feedback fail';
    fb.textContent = `Acertaste ${correct} de ${quiz.length}. Revisa el audio e inténtalo de nuevo.`;
    document.getElementById('btnCheck').style.display = 'none';
    document.getElementById('btnRetry').style.display = 'block';
  }
}

function retryQuiz() {
  if (!listeningState.quiz) return;
  renderQuiz(listeningState.quiz.questions);
}

function completeLesson(idx) {
  if (!listeningState.completed.includes(idx)) {
    if (typeof consumeLife === 'function' && !consumeLife()) {
      lsShowToast(typeof livesWaitMessage === 'function' ? livesWaitMessage() : 'Sin vidas. Espera 12 horas para que se restablezcan');
      return;
    }
    listeningState.completed.push(idx);
    try { localStorage.setItem('spkfm_ls', JSON.stringify(listeningState.completed)); } catch(e) {}
  }
  buildList();
  lsUpdateProgress();
  const extra = typeof livesLeftLabel === 'function' ? livesLeftLabel() : '';
  lsShowToast(`Lección ${idx + 1} completada ✓` + extra);
  const next = idx + 1;
  if (next < LABELS.length) {
    setTimeout(() => openLesson(next), 1100);
  } else {
    document.getElementById('quizCard').classList.remove('visible');
    lsShowToast('¡Has completado todas las lecciones! 🏆');
  }
}

function lsUpdateProgress() {
  const d = listeningState.completed.length, t = LABELS.length;
  document.getElementById('progressBadge').textContent = `${d} / ${t} completadas`;
  document.getElementById('mainBar').style.width = `${(d/t)*100}%`;
}

function lsShowToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg; t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2800);
}

/* ── PUNTO DE ENTRADA llamado desde app.js ── */
function buildListeningHub() {
  // Inject HTML structure into screen-listening
  const hub = document.getElementById('listeningHub');
  if (!hub) return;
  hub.innerHTML = `
    <div class="ls-wrap">
      <div class="ls-eyebrow">COMPRENSIÓN AUDITIVA</div>
      <h2 class="ls-title">Listening A1–A2</h2>
      <p class="ls-sub">Escucha cada audio y responde las 6 preguntas de comprensión. Debes acertar todas para desbloquear la siguiente lección.</p>
      <div class="progress-bar-wrap">
        <div class="progress-bar" id="mainBar" style="width:0%"></div>
      </div>
      <div class="lesson-list" id="lessonList"></div>
      <div class="player-card" id="playerCard">
        <div class="player-label">REPRODUCIENDO</div>
        <div class="player-title" id="playerTitle"></div>
        <audio id="audioEl" controls></audio>
        <p class="player-hint">🎧 Escucha el audio completo antes de responder las preguntas.</p>
        <span class="transcript-toggle" id="transcriptToggle" onclick="toggleTranscript()">Ver transcripción →</span>
        <div class="transcript-box" id="transcriptBox"></div>
        <button class="btn-start" onclick="startQuiz()">Responder preguntas →</button>
      </div>
      <div class="quiz-card" id="quizCard">
        <button class="back-btn" onclick="goBackToPlayer()">← Volver al audio</button>
        <div class="ls-eyebrow">COMPRENSIÓN · A1–A2</div>
        <div class="ls-quiz-title" id="quizTitle"></div>
        <div id="quizBody"></div>
        <div class="quiz-actions" id="quizActions" style="display:none">
          <button class="btn-check" id="btnCheck" onclick="checkAnswers()">Comprobar respuestas</button>
          <button class="btn-retry" id="btnRetry" onclick="retryQuiz()">Intentar de nuevo</button>
        </div>
        <div class="quiz-feedback" id="quizFeedback"></div>
      </div>
    </div>
  `;
  init();
}
